    s = 0.0
    for x_i in x:
        diff = x_i - m
        if not math.isfinite(diff):
            raise ValueError("logsumexp intermediate must be finite")
        z_i = math.exp(diff)
        if not math.isfinite(z_i):
            raise ValueError("logsumexp intermediate must be finite")
        z.append(z_i)
        s += z_i
        if not math.isfinite(s):
            raise ValueError("logsumexp intermediate must be finite")
    log_s = math.log(s)
    if not math.isfinite(log_s):
        raise ValueError("logsumexp intermediate must be finite")
    out_data = m + log_s
    if not math.isfinite(out_data):
        raise ValueError("logsumexp intermediate must be finite")
